#include <cstdint>
#include <string_view>

constexpr int hexDigit(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

consteval std::uint32_t rgb(std::string_view hex)
{
    if (hex.size() != 7 || hex[0] != '#')
    {
        throw "a colour must look like #RRGGBB";
    }
    std::uint32_t value{ 0 };
    for (std::size_t i{ 1 }; i < hex.size(); ++i)
    {
        const int digit{ hexDigit(hex[i]) };
        if (digit < 0)
        {
            throw "a colour may only contain hex digits";
        }
        value = value * 16 + static_cast<std::uint32_t>(digit);
    }
    return value;
}

unitTests:
static_assert(rgb("#FF8800") == 0xFF8800);
static_assert(rgb("#000000") == 0 && rgb("#ffffff") == 0xFFFFFF);
static_assert(rgb("#1a2B3c") == 0x1A2B3C);
constexpr std::uint32_t orange{ rgb("#FF8800") };

TEST("the result is an ordinary constant") { CHECK_EQ(orange, 0xFF8800u); CHECK_EQ((orange >> 16) & 0xFFu, 0xFFu); }

